import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CylinderGeometry, DirectionalLight, AmbientLight, Color, DoubleSide } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? config.visualSpec ?? {};
  const colors = spec.colors ?? {
    background: '#0b0b10', surface: '#16161d', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#191921' }, { at: 1, hex: '#121218' }]
  };
  const gStops = colors.gradientStops ?? [{ at: 0, hex: '#191921' }, { at: 1, hex: '#121218' }];
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const border = '#26262f';

  const root = new Group();
  root.name = config.id ?? 'feature-triptych';

  const disposables = [];
  const timelines = [];

  // ---- Backdrop stage plane (vertical gradient) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const gTop = color(new Color('#191921'));
  const gBot = color(new Color('#121218'));
  const grad = mix(gBot, gTop, smoothstep(0.0, 1.0, uv().y));
  backdropMat.colorNode = grad;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Lights (node-local) ----
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(-3, 3.5, 4);
  root.add(key);

  const rim = new DirectionalLight(new Color(accent), 0.9);
  rim.position.set(3.5, -2, 2);
  root.add(rim);

  // ---- Card content ----
  const cardData = [
    { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' }
  ];

  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const ROW_W = CARD_W * 3 + GAP * 2;
  const startX = -ROW_W / 2 + CARD_W / 2;

  const cardGroups = [];
  const textNodes = [];

  cardData.forEach((data, i) => {
    const cardGroup = new Group();
    const cx = startX + i * (CARD_W + GAP);
    cardGroup.position.set(cx, 0, 0);

    // Card face (albedo vertical ramp)
    const faceGeo = new PlaneGeometry(CARD_W, CARD_H);
    const faceMat = new MeshStandardNodeMaterial();
    const cTop = color(new Color(gStops[0].hex));
    const cBot = color(new Color(gStops[1].hex));
    faceMat.colorNode = mix(cBot, cTop, uv().y);
    faceMat.roughness = 0.6;
    faceMat.metalness = 0.25;
    faceMat.clearcoat = 0.15;
    const face = new Mesh(faceGeo, faceMat);
    face.position.z = 0.01;
    cardGroup.add(face);
    disposables.push(faceGeo, faceMat);

    // Hairline border (thin frame using slightly larger plane behind)
    const borderGeo = new PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
    const borderMat = new MeshStandardNodeMaterial();
    borderMat.colorNode = color(new Color(border));
    borderMat.roughness = 0.7;
    borderMat.metalness = 0.3;
    const borderMesh = new Mesh(borderGeo, borderMat);
    borderMesh.position.z = 0.0;
    cardGroup.add(borderMesh);
    disposables.push(borderGeo, borderMat);

    // Contact shadow plane under card
    const shadowGeo = new PlaneGeometry(CARD_W * 1.1, 0.4);
    const shadowMat = new MeshBasicNodeMaterial();
    shadowMat.transparent = true;
    shadowMat.opacity = 0.45;
    const shDist = uv().sub(vec3(0.5, 0.5, 0.0).xy).length();
    shadowMat.colorNode = vec4(0.0, 0.0, 0.0, smoothstep(0.5, 0.0, shDist));
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -CARD_H / 2 - 0.05, -0.02);
    cardGroup.add(shadow);
    disposables.push(shadowGeo, shadowMat);

    // Icon seat: machined disc
    const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 48);
    const discMat = new MeshStandardNodeMaterial();
    discMat.colorNode = color(new Color(colors.surface ?? '#16161d'));
    discMat.roughness = 0.55;
    discMat.metalness = 0.5;
    discMat.clearcoat = 0.2;
    const disc = new Mesh(discGeo, discMat);
    disc.rotation.x = Math.PI / 2;
    disc.position.set(0, CARD_H / 2 - 0.375 - 0.2, 0.04);
    cardGroup.add(disc);
    disposables.push(discGeo, discMat);

    // Glyph on disc
    const glyphNode = ctx.fontAtlas.createText(data.glyph, {
      fontSize: 40, color: accent, align: 'center'
    });
    glyphNode.position.set(0, disc.position.y, 0.09);
    cardGroup.add(glyphNode);
    textNodes.push(glyphNode);

    // Title
    const titleY = disc.position.y - 0.2 - 0.25;
    const titleNode = ctx.fontAtlas.createText(data.title, {
      fontSize: 40, color: paper, align: 'center', maxWidthPx: 400
    });
    titleNode.position.set(0, titleY, 0.05);
    cardGroup.add(titleNode);
    textNodes.push(titleNode);

    // Body
    const bodyY = titleY - 0.125 - 0.2;
    const bodyNode = ctx.fontAtlas.createText(data.body, {
      fontSize: 24, color: '#a8adba', align: 'center', maxWidthPx: 360, lineHeight: 1.5
    });
    bodyNode.position.set(0, bodyY, 0.05);
    cardGroup.add(bodyNode);
    textNodes.push(bodyNode);

    // store for hover: disc material for emissive
    discMat.emissive = new Color(accent);
    discMat.emissiveIntensity = 0.0;
    cardGroup.userData.discMat = discMat;
    cardGroup.userData.shadowMat = shadowMat;
    cardGroup.userData.shadow = shadow;

    root.add(cardGroup);
    cardGroups.push(cardGroup);
  });

  // ---- Entrance: stagger-cards fade-up ----
  const entranceTl = gsap.timeline();
  cardGroups.forEach((cg, i) => {
    cg.position.y = 0.2;
    entranceTl.to(cg.position, {
      y: 0, duration: 0.5, ease: 'power2.out'
    }, i * 0.08);
    entranceTl.fromTo(cg.scale,
      { x: 0.98, y: 0.98, z: 0.98 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      i * 0.08
    );
  });
  timelines.push(entranceTl);

  // ---- Hover handlers ----
  const hoverTweens = new Map();

  function hoverCard(cg, on) {
    const prev = hoverTweens.get(cg);
    if (prev) prev.kill();
    const tl = gsap.timeline();
    tl.to(cg.position, {
      y: on ? 0.06 : 0, z: on ? 0.12 : 0,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    tl.to(cg.userData.discMat, {
      emissiveIntensity: on ? 2.2 : 1.6,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    tl.to(cg.userData.shadow.scale, {
      x: on ? 1.25 : 1.0, y: on ? 1.15 : 1.0,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    tl.to(cg.userData.shadowMat, {
      opacity: on ? 0.55 : 0.45,
      duration: 0.18, ease: 'power2.out'
    }, 0);
    hoverTweens.set(cg, tl);
    timelines.push(tl);
  }

  // init emissive baseline
  cardGroups.forEach((cg) => { cg.userData.discMat.emissiveIntensity = 1.6; });

  root.userData.handlers = {
    onPointerOver: (e) => {
      const obj = e?.object;
      let cur = obj;
      while (cur && !cardGroups.includes(cur)) cur = cur.parent;
      if (cur) hoverCard(cur, true);
    },
    onPointerOut: (e) => {
      const obj = e?.object;
      let cur = obj;
      while (cur && !cardGroups.includes(cur)) cur = cur.parent;
      if (cur) hoverCard(cur, false);
      else cardGroups.forEach((cg) => hoverCard(cg, false));
    }
  };

  // ---- Idle breathing (subtle) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(root.rotation, { x: 0.015, duration: 6, ease: 'sine.inOut' });
  timelines.push(idleTl);

  root.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill());
    hoverTweens.forEach((t) => t && t.kill());
    disposables.forEach((d) => { try { d.dispose && d.dispose(); } catch (e) {} });
    textNodes.forEach((tn) => {
      tn.traverse && tn.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) { if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose()); else o.material.dispose(); }
      });
    });
  };

  return root;
}
